{"path":"assets/css/styles.css","content":"/* Core styles for aura_editorial layout */
:root{
  --bg:#fbfbfc;--muted:#6b7280;--accent:#5b7cfa;--accent-2:#7dd3fc;--card:#ffffff;--text:#0f172a;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;font-size:16px;color:var(--text);background:var(--bg);line-height:1.45}
.wrap{max-width:980px;margin:0 auto;padding:32px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter:blur(4px);position:sticky;top:0;z-index:30;border-bottom:1px solid rgba(15,23,42,0.05)}
.site-header .wrap{display:flex;gap:16px;align-items:center}
.logo{font-weight:700;color:var(--text);text-decoration:none}
.main-nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:6px}
.main-nav a.cta{background:var(--accent);color:white}
.try-btn{margin-left:12px;background:transparent;border:1px solid var(--accent);color:var(--accent);padding:8px 10px;border-radius:6px}
.hero{padding:64px 0;background-color:linear-gradient(180deg,#fff,#f7fbff);background-size:400px;background-repeat:repeat}
.headline{font-size:clamp(1.4rem,2.6vw,2.2rem);margin:0 0 12px}
.lede{color:var(--muted);margin:0 0 18px}
.hero-ctas{display:flex;gap:12px;align-items:center}
.primary{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;text-decoration:none}
.secondary{background:transparent;border:1px solid var(--accent);color:var(--accent);padding:8px 12px;border-radius:8px}
.contact{color:var(--muted);margin-top:14px}
/* sections */
section{padding:46px 0}
.reveal{opacity:0;transform:translateY(18px);transition:opacity 540ms cubic-bezier(.2,.9,.2,1),transform 540ms cubic-bezier(.2,.9,.2,1)}
.reveal.revealed{opacity:1;transform:none}
.diagnostic .bullets{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;margin-top:12px}
.plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:18px}
.card{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 6px 18px rgba(15,23,42,0.06)}
.price{font-weight:700;margin-top:8px}
.habits{display:flex;gap:12px;margin-top:12px}
.habit{background:linear-gradient(180deg,#fff,#f2fbff);padding:12px;border-radius:8px}
.fee-table{width:100%;border-collapse:collapse;margin-top:12px}
.fee-table th,.fee-table td{padding:8px 10px;text-align:left;border-bottom:1px solid rgba(15,23,42,0.05)}
.cta-row{display:flex;gap:12px;margin-top:12px}
.ghost{background:transparent;border:1px solid rgba(15,23,42,0.06);padding:8px 12px;border-radius:8px;text-decoration:none}
.site-footer{border-top:1px solid rgba(15,23,42,0.04);padding:28px 0;background:transparent}
.site-footer .columns{display:grid;grid-template-columns:1fr 1fr auto;gap:18px}
.small{font-size:.92rem}
.muted{color:var(--muted)}
.mini{font-size:.8rem;color:var(--muted);margin-top:12px}
/* modal */
.modal{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(2,6,23,0.4);backdrop-filter:blur(2px);visibility:hidden;opacity:0;transition:opacity .18s ease}
.modal[aria-hidden="false"]{visibility:visible;opacity:1}
.modal-panel{background:white;width:100%;max-width:720px;border-radius:12px;padding:20px;position:relative}
.modal-close{position:absolute;right:12px;top:12px;border:none;background:transparent;font-size:18px}
.tabs{display:flex;gap:8px;margin-bottom:12px}
.tab{background:transparent;border:1px solid rgba(15,23,42,0.06);padding:8px 10px;border-radius:8px}
.tab.active{background:var(--accent);color:white;border-color:var(--accent)}
.mode{display:block}
.mode[hidden]{display:none}
.breath-circle{width:160px;height:160px;border-radius:50%;margin:12px auto;background:linear-gradient(135deg,var(--accent-2),var(--accent));box-shadow:0 8px 30px rgba(91,124,250,0.12);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
.breath-circle.shrink{transform:scale(.6);transition:transform .9s ease}
.breath-circle.expand{transform:scale(1.05);transition:transform .9s ease}
.breath-controls{display:flex;gap:8px;align-items:center;justify-content:center;margin-top:12px}
textarea,input{width:100%;padding:10px;border:1px solid rgba(15,23,42,0.06);border-radius:8px}
.journal-actions,.intent-actions{display:flex;gap:8px;margin-top:8px}
/* accessible reduced motion */
@media (prefers-reduced-motion:reduce){
  .reveal{transition:none;opacity:1;transform:none}
  .breath-circle{transition:none}
}
/* pattern fallback for inline SVG file */
body.aura{background-color:var(--bg);background-image:url('/assets/img/pattern.svg');background-repeat:repeat}
@media (max-width:720px){
  .wrap{padding:18px}
  .site-header .wrap{flex-wrap:wrap}
  .main-nav{display:none}
}
"}
{"path":"assets/js/main.js","content":"(function(){
  // Utility
  function qs(sel,root=document){return root.querySelector(sel)}
  function qsa(sel,root=document){return Array.from(root.querySelectorAll(sel))}

  // Year in footer
  document.addEventListener('DOMContentLoaded',function(){qs('#year').textContent=new Date().getFullYear()})

  // Modal controls
  var modal=document.getElementById('exercise-modal');
  var openBtns=[document.getElementById('open-exercise'),document.getElementById('open-exercise-hero')];
  var closeBtn=document.getElementById('close-exercise');
  openBtns.forEach(function(b){if(b) b.addEventListener('click',openModal)});
  if(closeBtn) closeBtn.addEventListener('click',closeModal);
  function openModal(){modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';}
  function closeModal(){modal.setAttribute('aria-hidden','true');document.body.style.overflow='';}

  // Tabs
  var tabs=qsa('.tab');
  tabs.forEach(function(t){t.addEventListener('click',function(){
    tabs.forEach(function(x){x.classList.remove('active')});
    t.classList.add('active');
    var mode=t.dataset.mode;
    qsa('.mode').forEach(function(m){m.hidden = m.dataset.mode !== mode});
  })});

  // Breathing exercise
  var breathCircle=qs('#breath-circle');
  var startBtn=qs('#start-breath');
  var stopBtn=qs('#stop-breath');
  var breathText=qs('#breath-text');
  var breathDurationSelect=qs('#breath-duration');
  var breathTimer=null;var breathPhase=0; // 0 inhale,1 hold,2 exhale,3 hold

  function updateBreathVisual(phase){
    if(!breathCircle) return;
    if(phase===0 || phase===1){ breathCircle.classList.remove('shrink'); breathCircle.classList.add('expand'); }
    else { breathCircle.classList.remove('expand'); breathCircle.classList.add('shrink'); }
  }

  function tickBreath(totalSeconds){
    var start=Date.now();
    var cycle=4000; // 4s inhale, 2s hold, 4s exhale, 2s hold = 12s cycle
    var phases=[4,2,4,2];
    function step(){
      var elapsed=(Date.now()-start)/1000;
      if(elapsed>=totalSeconds){ stopBreath(); breathText.textContent='Complete.'; return }
      // determine phase by cycle position
      var pos=(elapsed*1000)%12000; // ms
      var accum=0; var pIdx=0;
      var phaseNames=['Inhale','Hold','Exhale','Hold'];
      var phaseMs=[4000,2000,4000,2000];
      for(var i=0;i<4;i++){ accum+=phaseMs[i]; if(pos<accum){pIdx=i;break}};
      updateBreathVisual(pIdx);
      breathText.textContent=phaseNames[pIdx]+" — " + Math.ceil((totalSeconds-elapsed)) + "s left";
      breathTimer=requestAnimationFrame(step);
    }
    breathTimer=requestAnimationFrame(step);
  }
  function startBreath(){
    var dur=Number(breathDurationSelect.value)||120;
    startBtn.disabled=true; stopBtn.disabled=false;
    breathText.textContent='Starting...';
    // respect prefers-reduced-motion
    if(window.matchMedia && window.matchMedia('(prefers-reduced-motion:reduce)').matches){
      breathText.textContent='Breathing support available. Reduced motion is active.';
      // simple countdown without animations
      var end=Date.now()+dur*1000;
      var t=setInterval(function(){
        var left=Math.ceil((end-Date.now())/1000);
        breathText.textContent='Time left: '+(left>0?left:0)+'s';
        if(left<=0){clearInterval(t); stopBreath(); breathText.textContent='Complete.'}
      },250);
      return;
    }
    tickBreath(dur);
  }
  function stopBreath(){
    startBtn.disabled=false; stopBtn.disabled=true;
    if(breathTimer) cancelAnimationFrame(breathTimer);
    breathTimer=null; breathCircle.classList.remove('expand','shrink');
  }
  if(startBtn) startBtn.addEventListener('click',startBreath);
  if(stopBtn) stopBtn.addEventListener('click',stopBreath);

  // Journaling storage
  var journalInput=qs('#journal-input');
  var saveJournal=qs('#save-journal');
  var clearJournal=qs('#clear-journal');
  var JOURNAL_KEY='pp_journal_entries_v1';
  if(saveJournal){saveJournal.addEventListener('click',function(){
    var text=(journalInput.value||'').trim();
    if(!text) return alert('Nothing to save.');
    var arr=[]; try{arr=JSON.parse(localStorage.getItem(JOURNAL_KEY) || '[]')}catch(e){arr=[]}
    arr.push({text:text,ts:new Date().toISOString()});
    localStorage.setItem(JOURNAL_KEY,JSON.stringify(arr));
    alert('Saved locally to this browser.');
  })}
  if(clearJournal){clearJournal.addEventListener('click',function(){journalInput.value=''; localStorage.removeItem(JOURNAL_KEY); alert('Cleared.')})}

  // Intention storage
  var intentInput=qs('#intention-input');
  var saveIntent=qs('#save-intent');
  var clearIntent=qs('#clear-intent');
  var currentIntent=qs('#current-intent');
  var INTENT_KEY='pp_current_intent_v1';
  function loadIntent(){ try{var v=localStorage.getItem(INTENT_KEY); if(v){currentIntent.textContent='Current intention: "'+v+'"';}}catch(e){}
  }
  if(saveIntent){saveIntent.addEventListener('click',function(){var v=(intentInput.value||'').trim(); if(!v) return alert('Write an intention to set it.'); localStorage.setItem(INTENT_KEY,v); loadIntent();})}
  if(clearIntent){clearIntent.addEventListener('click',function(){localStorage.removeItem(INTENT_KEY); intentInput.value=''; currentIntent.textContent='No intention set.'})}
  loadIntent();

  // Scroll reveal implementation with prefers-reduced-motion
  var revealEls = qsa('.reveal');
  var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion:reduce)').matches;
  if(prefersReduced){ revealEls.forEach(function(el){el.classList.add('revealed')}); }
  else{
    function onScroll(){
      var h = window.innerHeight;
      revealEls.forEach(function(el){
        var r = el.getBoundingClientRect();
        if(r.top < h - (h*0.12)) el.classList.add('revealed');
      });
    }
    onScroll();
    window.addEventListener('scroll', throttle(onScroll, 120));
    window.addEventListener('resize', throttle(onScroll, 200));
  }

  // throttle helper
  function throttle(fn, wait){var t=null, last=0;return function(){var now=Date.now(); if(last && now-last < wait) return; last=now; fn();}}

  // Close modal on ESC
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeModal(); });

})();
"}
